  for (let page = 1; page <= 5 && !found; page++) {
    const list = await client.nfts.getList({ page, per_page: 250 });
    found = list.find(x => x.name === 'Bored Ape Yacht Club');
    if (found) break;
  }
  if (!found) return { error: 'not found' };
  const detail = await client.nfts.getID(found.id);
  return { id: found.id, contract_address: detail.contract_address };
}

